"""Fail-closed comparison of observations; this alone reads expectations."""
from __future__ import annotations

from collections import Counter
from corpus import ENGINES, FACT_IDS, validate_contract, validate_registry
from normalize import ordered
from capture import fixture_input_digest
from pathlib import Path
import hashlib


_STAGE_ORDER = {"lex": 0, "parse": 1, "moduleGraph": 2, "nameResolution": 3, "substitution": 4, "level": 5, "sourceEvidence": 6}


def fact_value(observation, fact):
    item = observation.get("facts", {}).get(fact, {})
    if item.get("capability") != "supported":
        raise ValueError(f"{fact} is not observed")
    return item["value"]


def projection(fact, value):
    if fact == "variables":
        return ordered([{key: row[key] for key in ("name", "declaredIn", "declaredName")} for row in value])
    if fact == "resolution":
        return {key: ordered(value[key]) for key in ("dependencies", "operators")}
    return ordered(value) if isinstance(value, list) else value


def compare_corpus(captured, observations, registry, identities=None):
    """Return comparison rows, coverage and verdict with fixed denominators.

    Reviewed entries have exact per-engine expected values per fact:
    expected[fact] = {"mirrors": value, "sany"|"apalache": value}.
    No entry can excuse an execution failure or missing observation.
    """
    validate_registry(registry, captured.fixtures)
    rows = []

    def add(fixture, engine, fact, status, detail, expected=None, actual=None):
        rows.append({"fixture": fixture, "engine": engine, "fact": fact,
                     "status": status, "detail": detail, "expected": expected, "actual": actual})

    by_key = {}
    fixture_map = {fixture.id: fixture for fixture in captured.fixtures}
    for observation in observations:
        try:
            if not isinstance(observation, dict):
                raise ValueError("observation must be an object")
            validate_contract("observation", observation)
            key = (observation["fixture"], observation["engine"])
            if key in by_key or key[0] not in fixture_map:
                raise ValueError("duplicate or unknown observation row")
            if observation["provider"] != fixture_map[key[0]].provider:
                raise ValueError("observation provider differs from captured provider")
            if identities is not None:
                if observation["inputDigest"] != fixture_input_digest(fixture_map[key[0]]):
                    raise ValueError("observation input digest differs from frozen capture")
                if observation["execution"] == "completed":
                    if observation["tool"] != identities["tools"].get(key[1]):
                        raise ValueError("observation tool differs from verified tool identity")
                    artifacts = observation["rawArtifacts"]
                    if not any("stdout" in ref["path"] for ref in artifacts) or not any("stderr" in ref["path"] for ref in artifacts):
                        raise ValueError("completed observation lacks stdout/stderr evidence")
                    evidence_root = Path(identities["evidenceRoot"]).resolve()
                    for ref in artifacts:
                        path = evidence_root / ref["path"]
                        if not path.resolve().is_relative_to(evidence_root) or path.is_symlink() or not path.is_file():
                            raise ValueError("invalid raw evidence path")
                        if hashlib.sha256(path.read_bytes()).hexdigest() != ref["sha256"]:
                            raise ValueError("raw evidence hash mismatch")
            by_key[key] = observation
        except (ValueError, KeyError, TypeError) as error:
            fixture = observation.get("fixture", "?") if isinstance(observation, dict) else "?"
            engine = observation.get("engine", "?") if isinstance(observation, dict) else "?"
            add(fixture, engine, "observation", "fail", str(error))

    used = set()
    reviewed = registry["reviewed"]
    valid_entries = []
    entry_ids = {entry["id"] for entry in registry["candidates"]}
    for entry in reviewed:
        required = {"id", "fixtureIds", "fields", "expected", "profile", "sourceDigests", "enginePins", "rationale", "evidence", "review", "revisit"}
        try:
            if not isinstance(entry, dict) or set(entry) != required or not entry["fixtureIds"] or not entry["fields"]:
                raise ValueError("invalid reviewed entry fields")
            if entry["id"] in entry_ids:
                raise ValueError("duplicate difference ID")
            entry_ids.add(entry["id"])
            if len(set(entry["fixtureIds"])) != len(entry["fixtureIds"]) or len(set(entry["fields"])) != len(entry["fields"]) or not entry["revisit"]:
                raise ValueError("duplicate scope or missing revisit condition")
            if entry["profile"] != captured.profile or not entry["rationale"] or not entry["evidence"]:
                raise ValueError("missing profile/rationale/evidence")
            if not entry["review"].get("artifact") or not entry["review"].get("commit"):
                raise ValueError("missing review provenance")
            if set(entry["fields"]) - set(FACT_IDS) or set(entry["fixtureIds"]) - set(fixture_map):
                raise ValueError("unknown fixture/field")
            for fid in entry["fixtureIds"]:
                expected_sources = {source.logical_path: source.sha256 for source in fixture_map[fid].supplied_sources}
                if entry["sourceDigests"].get(fid) != expected_sources:
                    raise ValueError("stale source digests")
            if set(entry["expected"]) != set(entry["fields"]) or len(entry["enginePins"]) != 2 or "mirrors" not in entry["enginePins"]:
                raise ValueError("difference expected/pin scope is not exact")
            for field in entry["fields"]:
                if set(entry["expected"][field]) != set(entry["enginePins"]):
                    raise ValueError("difference expected engine scope mismatch")
            if identities is not None:
                for engine, fingerprint in entry["enginePins"].items():
                    known = identities["tools"].get(engine) or identities.get("expectedTools", {}).get(engine)
                    if known is not None and known.get("fingerprint") != fingerprint:
                        raise ValueError("difference pins differ from verified artifacts")
                review_root = Path(identities["reviewRoot"]).resolve()
                refs = entry["evidence"] + [{"path": entry["review"]["artifact"], "sha256": entry["review"].get("sha256")}]
                for ref in refs:
                    if not isinstance(ref, dict) or set(ref) != {"path", "sha256"}:
                        raise ValueError("review evidence requires exact path and hash")
                    path = review_root / ref["path"]
                    if Path(ref["path"]).is_absolute() or not path.resolve().is_relative_to(review_root) or path.is_symlink() or not path.is_file():
                        raise ValueError("review evidence path is invalid")
                    if hashlib.sha256(path.read_bytes()).hexdigest() != ref["sha256"]:
                        raise ValueError("review evidence hash mismatch")
            valid_entries.append(entry)
        except (ValueError, KeyError, TypeError) as error:
            label = entry.get("id", "?") if isinstance(entry, dict) else "?"
            add("registry", "registry", "reviewed", "fail", f"{label}: {error}")

    def compare(fid, engine, fact, left, right):
        if left == right:
            add(fid, engine, fact, "match", "equal", left, right)
            return
        for entry in valid_entries:
            if fid not in entry["fixtureIds"] or fact not in entry["fields"]:
                continue
            pair = entry["expected"].get(fact)
            obs = by_key[(fid, engine)]
            mirror = by_key[(fid, "mirrors")]
            if pair == {"mirrors": left, engine: right} and entry["enginePins"] == {
                "mirrors": mirror["tool"]["fingerprint"], engine: obs["tool"]["fingerprint"]}:
                used.add((entry["id"], fid, engine, fact))
                add(fid, engine, fact, "reviewed_difference", entry["id"], left, right)
                return
        add(fid, engine, fact, "fail", "unreviewed disagreement", left, right)

    for fixture in captured.fixtures:
        available = {}
        for engine in ENGINES:
            observation = by_key.get((fixture.id, engine))
            if observation is None:
                add(fixture.id, engine, "observation", "incomplete", "missing required fixture row")
            elif observation["execution"] != "completed" or observation["outcome"] == "unknown":
                add(fixture.id, engine, "outcome", "incomplete", observation["execution"])
            else:
                available[engine] = observation
        digests = {o["inputDigest"] for engine in ENGINES if (o := by_key.get((fixture.id, engine))) is not None}
        if len(digests) > 1:
            add(fixture.id, "all", "input", "fail", "engines observed different inputs")
        mirror = available.get("mirrors")
        if mirror:
            add(fixture.id, "mirrors", "outcome", "match" if mirror["outcome"] == fixture.kind else "fail",
                "manifest outcome", fixture.kind, mirror["outcome"])
            try:
                actual = fact_value(mirror, "stage")
                expected = {"stage": fixture.expected_stage, "reason": fixture.reason}
                if fixture.kind == "accepted":
                    matches = actual.get("reason") is None and _STAGE_ORDER.get(actual.get("stage"), -1) >= _STAGE_ORDER[fixture.expected_stage]
                    detail = "completed pipeline reaches exercised stage"
                else:
                    matches, detail = expected == actual, "manifest stage/reason"
                add(fixture.id, "mirrors", "stage", "match" if matches else "fail", detail, expected, actual)
            except (ValueError, KeyError) as error:
                add(fixture.id, "mirrors", "stage", "incomplete", str(error))
            if fixture.summary and mirror["outcome"] == "accepted":
                try:
                    golden_facts = [
                        ("variables", fixture.summary["effectiveVariables"], fact_value(mirror, "variables")),
                        ("source_closure", ordered([{"module": source["logicalPath"][:-4], "path": source["logicalPath"], "sha256": source["sha256"]} for source in fixture.summary["sources"]]), projection("source_closure", fact_value(mirror, "source_closure"))),
                    ]
                    local_dependencies = [{"owner": edge["owner"], "dependency": edge["module"], "kind": edge["kind"], "local": edge["local"]}
                                          for edge in fixture.summary.get("dependencies", []) if edge["resolution"] == "local"]
                    golden_facts.append(("dependencies", ordered(local_dependencies), projection("resolution", fact_value(mirror, "resolution"))["dependencies"]))
                    if fixture.summary.get("levels") is not None:
                        expected_levels = fixture.summary["levels"]
                        actual_levels = {item["name"]: item["level"] for item in fact_value(mirror, "levels") if item["name"] in expected_levels}
                        golden_facts.append(("levels", expected_levels, actual_levels))
                    for fact, expected, actual in golden_facts:
                        add(fixture.id, "mirrors", fact, "match" if expected == actual else "fail", "frozen summary", expected, actual)
                except (ValueError, KeyError, TypeError) as error:
                    add(fixture.id, "mirrors", "summary", "incomplete", str(error))
        for engine in ("sany", "apalache"):
            other = available.get(engine)
            if not mirror or not other:
                continue
            compare(fixture.id, engine, "outcome", mirror["outcome"], other["outcome"])
            # Native stage mapping is independently calibrated, never guessed.
            if other["stage"] is None:
                add(fixture.id, engine, "stage", "unsupported", "native stages have no qualified Mirrors mapping")
            elif mirror["outcome"] == other["outcome"] == "rejected":
                compare(fixture.id, engine, "stage", mirror["stage"], other["stage"])
            for requirement in fixture.requirements[engine]:
                fact = requirement.id
                if fact in ("outcome", "stage") or not requirement.applicable:
                    continue
                if mirror["outcome"] != "accepted" or other["outcome"] != "accepted":
                    add(fixture.id, engine, fact, "not_applicable", "no mutually accepted semantic graph")
                    continue
                try:
                    compare(fixture.id, engine, fact, projection(fact, fact_value(mirror, fact)), projection(fact, fact_value(other, fact)))
                except (ValueError, KeyError, TypeError) as error:
                    add(fixture.id, engine, fact, "incomplete" if requirement.required else "unsupported", str(error))
        if "sany" in available and "apalache" in available:
            left, right = available["sany"]["outcome"], available["apalache"]["outcome"]
            add(fixture.id, "oracles", "outcome", "match" if left == right else "oracle_disagreement", "reference-to-reference", left, right)
    for entry in valid_entries:
        required_uses = {(entry["id"], fid, engine, field) for fid in entry["fixtureIds"] for engine in entry["enginePins"] if engine != "mirrors" for field in entry["fields"]}
        for use in required_uses - used:
            _, fid, engine, _ = use
            evaluable = all(by_key.get((fid, side), {}).get("execution") == "completed" and
                by_key.get((fid, side), {}).get("outcome") != "unknown" for side in ("mirrors", engine))
            add(fid, engine, "reviewed", "fail" if evaluable else "incomplete",
                f"unused reviewed difference: {entry['id']}" if evaluable else f"reviewed difference could not execute: {entry['id']}")
    counts = Counter(row["status"] for row in rows)
    coverage = {"fixtures": len(captured.fixtures), "branches": len(captured.branch_ids), "expectedObservations": len(captured.fixtures) * len(ENGINES),
                "observations": len(observations), "comparisons": dict(sorted(counts.items())),
                "byEngine": {engine: dict(Counter(row["status"] for row in rows if row["engine"] == engine)) for engine in ENGINES},
                "branchFixtures": {branch: [f.id for f in captured.fixtures if branch in f.branches] for branch in captured.branch_ids}}
    verdict = "fail" if counts["fail"] else "incomplete" if counts["incomplete"] else "pass"
    return rows, coverage, verdict

code.tools/tla-differential/corpus.py:
"""Frozen DV0 corpus capture and closed JSON contract validation.

This module deliberately captures normalized bytes before a runner is introduced.
It never infers a reachable closure from an expected summary: that is an adapter
observation in DV2/DV3.  Expected summaries only validate the corpus declaration.
"""
from __future__ import annotations

import hashlib
import json
import re
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Mapping

CORPUS_SCHEMA = "mirrors.tla-frontend-corpus/1"
SUMMARY_SCHEMA = "mirrors.tla-frontend-summary/1"
OBSERVATION_SCHEMA = "mirrors.tla-differential-observation/v1"
REPORT_SCHEMA = "mirrors.tla-differential-report/v1"
REGISTRY_SCHEMA = "mirrors.tla-differential-differences/v1"
LOCK_SCHEMA = "mirrors.tla-differential-toolchain-lock/v1"
FACT_IDS = ("outcome", "stage", "source_closure", "variables", "resolution", "substitution", "levels")
ENGINES = ("mirrors", "sany", "apalache")
_STAGES = {"lex", "parse", "moduleGraph", "nameResolution", "substitution", "level", "sourceEvidence"}
MAX_SOURCE_BYTES = 1 * 1024 * 1024
MAX_JSON_BYTES = 8 * 1024 * 1024
MAX_CAPTURE_BYTES = 64 * 1024 * 1024


class CorpusError(ValueError):
    pass


@dataclass(frozen=True)
class SourceFile:
    logical_path: str
    sha256: str
    byte_length: int
    normalized_bytes: bytes


@dataclass(frozen=True)
class FactRequirement:
    id: str
    applicable: bool
    required: bool


@dataclass(frozen=True)
class FixtureCapture:
    id: str
    kind: str
    expected_stage: str
    reason: str | None
    provider: str
    root: str
    source_root: str | None
    inline_source_map: tuple[Mapping[str, str], ...]
    branches: tuple[str, ...]
    manifest_expectation: Mapping[str, Any]
    summary: Mapping[str, Any] | None
    summary_sha256: str | None
    supplied_sources: tuple[SourceFile, ...]
    expected_reachable_sources: tuple[SourceFile, ...] | None
    requirements: Mapping[str, tuple[FactRequirement, ...]]


@dataclass(frozen=True)
class CorpusCapture:
    profile: str
    fixtures: tuple[FixtureCapture, ...]
    branch_ids: tuple[str, ...]
    manifest_sha256: str
    profile_sha256: str
    summary_sha256: str
    registry_sha256: str


def _digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _read_limited(path: Path, limit: int, label: str) -> bytes:
    try:
        if path.stat().st_size > limit:
            raise CorpusError(f"{label} exceeds {limit} byte bound: {path}")
        raw = path.read_bytes()
    except OSError as error:
        raise CorpusError(f"cannot read {label} {path}: {error}") from error
    if len(raw) > limit:
        raise CorpusError(f"{label} exceeds {limit} byte bound: {path}")
    return raw


def _read_json(path: Path) -> tuple[dict[str, Any], bytes]:
    try:
        raw = _read_limited(path, MAX_JSON_BYTES, "JSON input")
        data = json.loads(raw)
    except (CorpusError, json.JSONDecodeError) as error:
        raise CorpusError(f"cannot read JSON {path}: {error}") from error
    if not isinstance(data, dict):
        raise CorpusError(f"{path}: root must be an object")
    return data, raw


def _relative(path: str, label: str) -> None:
    value = Path(path)
    if not path or value.is_absolute() or ".." in value.parts:
        raise CorpusError(f"{label}: path must be nonempty and relative: {path!r}")


def _normalized(data: bytes) -> bytes:
    return data.replace(b"\r\n", b"\n").replace(b"\r", b"\n")


def _source(root: Path, logical_path: str, label: str) -> SourceFile:
    _relative(logical_path, label)
    path = root
    for component in Path(logical_path).parts:
        path /= component
        if path.is_symlink():
            raise CorpusError(f"{label}: symlink source component: {logical_path}")
    try:
        if not path.is_file():
            raise OSError("source is not a regular file")
        raw = _read_limited(path, MAX_SOURCE_BYTES, "source")
    except OSError as error:
        raise CorpusError(f"{label}: missing source {logical_path}") from error
    normalized = _normalized(raw)
    try:
        normalized.decode("utf-8", errors="strict")
    except UnicodeDecodeError as error:
        raise CorpusError(f"{label}: source is not valid UTF-8: {logical_path}") from error
    return SourceFile(logical_path, _digest(normalized), len(normalized), normalized)


def _requirements(kind: str) -> Mapping[str, tuple[FactRequirement, ...]]:
    accepted = kind == "accepted"
    out: dict[str, tuple[FactRequirement, ...]] = {}
    for engine in ENGINES:
        facts = [FactRequirement("outcome", True, True), FactRequirement("stage", True, engine == "mirrors")]
        for fact in FACT_IDS[2:]:
            # SANY structural facts are initially required for accepted cases;
            # Apalache remains applicable but unqualified until DV1 publishes capability evidence.
            facts.append(FactRequirement(fact, accepted, engine == "sany" and accepted))
        out[engine] = tuple(facts)
    return out


def validate_manifest(manifest: Mapping[str, Any], fixture_root: Path) -> tuple[FixtureCapture, ...]:
    if manifest.get("schema") != CORPUS_SCHEMA:
        raise CorpusError("unknown corpus schema")
    profile = manifest.get("profile")
    if not isinstance(profile, str) or not profile:
        raise CorpusError("manifest profile must be a nonempty string")
    stages = manifest.get("stages")
    if not isinstance(stages, list) or not stages or len(stages) != len(set(stages)) or set(stages) - _STAGES:
        raise CorpusError("manifest stages are invalid")
    branches = manifest.get("branches")
    if not isinstance(branches, list):
        raise CorpusError("manifest branches must be an array")
    branch_ids = [row.get("id") for row in branches if isinstance(row, dict)]
    if len(branch_ids) != len(branches) or any(not isinstance(x, str) or not x for x in branch_ids) or len(set(branch_ids)) != len(branch_ids):
        raise CorpusError("manifest branch IDs are invalid")
    fixtures = manifest.get("fixtures")
    if not isinstance(fixtures, list):
        raise CorpusError("manifest fixtures must be an array")
    captures: list[FixtureCapture] = []
    seen: set[str] = set()
    for row in fixtures:
        if not isinstance(row, dict):
            raise CorpusError("fixture must be an object")
        fixture_id, kind, stage = row.get("id"), row.get("kind"), row.get("stage")
        if not isinstance(fixture_id, str) or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]*", fixture_id) or fixture_id in seen:
            raise CorpusError(f"duplicate or invalid fixture ID: {fixture_id!r}")
        seen.add(fixture_id)
        if kind not in {"accepted", "rejected"} or stage not in stages:
            raise CorpusError(f"fixture {fixture_id}: invalid kind or stage")
        reason = row.get("reason")
        if (kind == "accepted" and reason is not None) or (kind == "rejected" and reason not in {"malformed", "limit", "profile_limit"}):
            raise CorpusError(f"fixture {fixture_id}: invalid reason")
        provider, root = row.get("provider"), row.get("root")
        if provider not in {"borrowed-directory", "inline-source-map"} or not isinstance(root, str) or not root:
            raise CorpusError(f"fixture {fixture_id}: invalid provider or root")
        source_root = row.get("sourceRoot")
        if provider == "borrowed-directory" and not isinstance(source_root, str):
            raise CorpusError(f"fixture {fixture_id}: borrowed provider needs sourceRoot")
        if provider == "inline-source-map" and "sourceRoot" in row:
            raise CorpusError(f"fixture {fixture_id}: inline provider cannot carry sourceRoot")
        if source_root is not None:
            if not isinstance(source_root, str):
                raise CorpusError(f"fixture {fixture_id}: invalid sourceRoot")
            _relative(source_root, f"fixture {fixture_id}")
        paths = row.get("files")
        if not isinstance(paths, list) or not paths or any(not isinstance(x, str) for x in paths) or len(set(paths)) != len(paths):
            raise CorpusError(f"fixture {fixture_id}: source files must be unique nonempty paths")
        for source_path in paths:
            _relative(source_path, f"fixture {fixture_id}")
        if provider == "borrowed-directory":
            assert isinstance(source_root, str)
            for source_path in paths:
                try:
                    Path(source_path).relative_to(source_root)
                except ValueError as error:
                    raise CorpusError(f"fixture {fixture_id}: borrowed source is outside sourceRoot: {source_path}") from error
        supplied = tuple(_source(fixture_root, path, f"fixture {fixture_id}") for path in paths)
        if provider == "borrowed-directory" and "inlineSourceMap" in row:
            raise CorpusError(f"fixture {fixture_id}: borrowed provider cannot carry inlineSourceMap")
        inline = row.get("inlineSourceMap", [])
        if not isinstance(inline, list) or (provider == "inline-source-map" and not inline):
            raise CorpusError(f"fixture {fixture_id}: invalid inline source map")
        maps: list[Mapping[str, str]] = []
        logical_names: set[str] = set()
        mapped_files: set[str] = set()
        for entry in inline:
            if not isinstance(entry, dict) or set(entry) != {"file", "logicalName"} or entry["file"] not in paths or not isinstance(entry["logicalName"], str) or not entry["logicalName"] or entry["logicalName"] in logical_names:
                raise CorpusError(f"fixture {fixture_id}: invalid inline source map entry")
            _relative(f"{entry['logicalName']}.tla", f"fixture {fixture_id}")
            logical_names.add(entry["logicalName"])
            mapped_files.add(entry["file"])
            maps.append({"file": entry["file"], "logicalName": entry["logicalName"]})
        if provider == "inline-source-map" and mapped_files != set(paths):
            raise CorpusError(f"fixture {fixture_id}: inline source map must cover every source exactly once")
        fixture_branches = row.get("branches")
        if not isinstance(fixture_branches, list) or not fixture_branches or any(x not in branch_ids for x in fixture_branches):
            raise CorpusError(f"fixture {fixture_id}: unknown branch")
        summary: Mapping[str, Any] | None = None
        summary_sha256: str | None = None
        expected_reachable: tuple[SourceFile, ...] | None = None
        summary_path = row.get("summary")
        if kind == "accepted":
            if not isinstance(summary_path, str):
                raise CorpusError(f"fixture {fixture_id}: accepted fixture needs summary")
            _relative(summary_path, f"fixture {fixture_id}")
            summary, summary_raw = _read_json(fixture_root / summary_path)
            summary_sha256 = _digest(summary_raw)
            if summary.get("schema") != SUMMARY_SCHEMA or summary.get("fixture") != fixture_id or summary.get("root") != root or summary.get("profile") != profile:
                raise CorpusError(f"fixture {fixture_id}: summary identity mismatch")
            source_rows = summary.get("sources")
            if not isinstance(source_rows, list):
                raise CorpusError(f"fixture {fixture_id}: summary has no sources")
            supplied_by_name = {Path(x.logical_path).name: x for x in supplied}
            reachable: list[SourceFile] = []
            for source_row in source_rows:
                if not isinstance(source_row, dict) or set(source_row) != {"logicalPath", "sha256"}:
                    raise CorpusError(f"fixture {fixture_id}: malformed summary source")
                logical_path, digest = source_row["logicalPath"], source_row["sha256"]
                actual = supplied_by_name.get(logical_path)
                if actual is None or digest != actual.sha256:
                    raise CorpusError(f"fixture {fixture_id}: summary source hash mismatch for {logical_path}")
                reachable.append(actual)
            if len({x.logical_path for x in reachable}) != len(reachable):
                raise CorpusError(f"fixture {fixture_id}: duplicate summary source")
            expected_reachable = tuple(reachable)
        elif summary_path is not None:
            raise CorpusError(f"fixture {fixture_id}: rejected fixture carries summary")
        captures.append(FixtureCapture(fixture_id, kind, stage, reason, provider, root, source_root, tuple(maps), tuple(fixture_branches), dict(row), summary, summary_sha256, supplied, expected_reachable, _requirements(kind)))
    return tuple(captures)


def load_corpus(repo_root: Path | str) -> CorpusCapture:
    repo = Path(repo_root)
    fixture_root = repo / "test/fixtures/tla-frontend"
    manifest, manifest_raw = _read_json(fixture_root / "manifest.json")
    captures = validate_manifest(manifest, fixture_root)
    profile_path = repo / "Docs/model-interface-compiler/tla-language-profile.md"
    registry_path = fixture_root / "differential/differences.json"
    try:
        profile_raw = _read_limited(profile_path, MAX_JSON_BYTES, "profile")
        registry, registry_raw = _read_json(registry_path)
    except OSError as error:
        raise CorpusError(f"missing DV0 input: {error.filename}") from error
    validate_registry(registry, captures)
    captured_bytes = sum({source.logical_path: source.byte_length for fixture in captures for source in fixture.supplied_sources}.values())
    if captured_bytes > MAX_CAPTURE_BYTES:
        raise CorpusError(f"captured sources exceed {MAX_CAPTURE_BYTES} byte bound")
    listed = {source.logical_path for fixture in captures for source in fixture.supplied_sources}
    # Evidence may contain native output directories named Module.tla. Only
    # accepted/rejected source namespaces are fixture inputs, never reports.
    physical = {path.relative_to(fixture_root).as_posix()
        for directory in (fixture_root / "accepted", fixture_root / "rejected")
        for path in directory.rglob("*.tla") if path.is_file() or path.is_symlink()}
    if listed != physical:
        raise CorpusError(f"manifest files do not account for fixture sources: {sorted(listed ^ physical)}")
    summary_digest = hashlib.sha256()
    for fixture in captures:
        if fixture.summary_sha256 is not None:
            summary_digest.update(fixture.summary_sha256.encode())
    return CorpusCapture(str(manifest["profile"]), captures, tuple(row["id"] for row in manifest["branches"]), _digest(manifest_raw), _digest(profile_raw), summary_digest.hexdigest(), _digest(registry_raw))


def validate_corpus(repo_root: Path | str) -> CorpusCapture:
    return load_corpus(repo_root)


def validate_contract(name: str, value: Mapping[str, Any]) -> None:
    """Small closed-schema validator for DV0 boundaries, with no third-party dependency."""
    if not isinstance(value, dict):
        raise CorpusError(f"{name}: root must be an object")
    schemas = {
        "observation": (OBSERVATION_SCHEMA, {"schema", "fixture", "engine", "provider", "inputDigest", "adapter", "tool", "invocation", "execution", "outcome", "nativePhase", "stage", "diagnostics", "facts", "rawArtifacts"}, {"schema", "fixture", "engine", "provider", "inputDigest", "adapter", "tool", "invocation", "execution", "outcome", "nativePhase", "stage", "diagnostics", "facts", "rawArtifacts"}),
        "report": (REPORT_SCHEMA, {"schema", "inputs", "observations", "comparisons", "coverage", "verdict"}, {"schema", "inputs", "observations", "comparisons", "coverage", "verdict"}),
        "registry": (REGISTRY_SCHEMA, {"schema", "candidates", "reviewed"}, {"schema", "candidates", "reviewed"}),
        "lock": (LOCK_SCHEMA, {"schema", "tools"}, {"schema", "tools"}),
    }
    if name not in schemas:
        raise CorpusError(f"unknown contract {name}")
    schema, allowed, required = schemas[name]
    if value.get("schema") != schema or set(value) - allowed or not required <= set(value):
        raise CorpusError(f"{name}: wrong schema, missing field, or unknown field")
    if name == "registry":
        candidates = value["candidates"]
        if not isinstance(candidates, list): raise CorpusError("registry: candidates must be an array")
        ids: set[str] = set()
        for candidate in candidates:
            required_candidate = {"id", "fixtureIds", "fields", "expected", "profile", "sourceDigests", "rationale", "revisit", "reviewStatus"}
            if not isinstance(candidate, dict) or set(candidate) - (required_candidate | {"evidence"}) or not required_candidate <= set(candidate) or candidate["reviewStatus"] != "unreviewed" or candidate["id"] in ids:
                raise CorpusError("registry: invalid or non-unreviewed candidate")
            ids.add(candidate["id"])
        reviewed = value["reviewed"]
        if not isinstance(reviewed, list): raise CorpusError("registry: reviewed must be an array")
    elif name == "observation":
        if value["engine"] not in ENGINES or value["provider"] not in {"borrowed-directory", "inline-source-map"} or value["execution"] not in {"completed", "unavailable", "timeout", "crash", "invalid_output", "resource_exhausted"} or value["outcome"] not in {"accepted", "rejected", "unknown"}:
            raise CorpusError("observation: invalid engine, provider, execution, or outcome")
        if not isinstance(value["inputDigest"], str) or len(value["inputDigest"]) != 64 or any(char not in "0123456789abcdef" for char in value["inputDigest"]):
            raise CorpusError("observation: inputDigest must be lowercase SHA-256")
        _identity(value["adapter"], {"id", "version"}, "adapter")
        _identity(value["tool"], {"id", "version", "fingerprint"}, "tool")
        invocation = value["invocation"]
        if not isinstance(invocation, dict) or set(invocation) != {"argv", "exitCode"} or not isinstance(invocation["argv"], list) or not all(isinstance(arg, str) for arg in invocation["argv"]) or (invocation["exitCode"] is not None and (not isinstance(invocation["exitCode"], int) or isinstance(invocation["exitCode"], bool))):
            raise CorpusError("observation: invalid invocation")
        if value["nativePhase"] is not None and not isinstance(value["nativePhase"], str) or value["stage"] is not None and not isinstance(value["stage"], str):
            raise CorpusError("observation: invalid native phase or stage")
        if not isinstance(value["diagnostics"], list) or not all(isinstance(item, dict) for item in value["diagnostics"]):
            raise CorpusError("observation: diagnostics must be objects")
        _artifacts(value["rawArtifacts"])
        if value["execution"] != "completed" and value["outcome"] != "unknown":
            raise CorpusError("observation: incomplete execution cannot have a language outcome")
        facts = value["facts"]
        if not isinstance(facts, dict): raise CorpusError("observation: facts must be an object")
        for fact_id, fact in facts.items():
            if fact_id not in FACT_IDS or not isinstance(fact, dict) or set(fact) - {"capability", "value"} or "capability" not in fact or fact["capability"] not in {"supported", "unsupported", "unqualified"} or (fact["capability"] == "supported" and "value" not in fact) or (fact["capability"] != "supported" and "value" in fact):
                raise CorpusError("observation: invalid fact observation")
            if fact["capability"] == "supported":
                _fact_value(fact_id, fact["value"])
                if fact_id == "outcome" and fact["value"] != value["outcome"]:
                    raise CorpusError("observation: outcome fact disagrees with outcome")
                if fact_id == "stage" and (not isinstance(fact["value"], dict) or fact["value"]["stage"] != value["stage"]):
                    raise CorpusError("observation: stage fact disagrees with stage")
                if value["outcome"] == "rejected" and fact_id not in {"outcome", "stage"}:
                    raise CorpusError("observation: rejected output cannot carry semantic facts")
        if value["execution"] == "completed" and value["outcome"] != "unknown":
            outcome_fact = facts.get("outcome")
            if not isinstance(outcome_fact, dict) or outcome_fact.get("capability") != "supported":
                raise CorpusError("observation: completed known outcome needs supported outcome fact")


def _identity(value: Any, keys: set[str], label: str) -> None:
    if not isinstance(value, dict) or set(value) != keys or not all(isinstance(value[key], str) and value[key] for key in keys):
        raise CorpusError(f"observation: invalid {label}")


def _exact_object(value: Any, keys: set[str], label: str) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != keys:
        raise CorpusError(f"observation: invalid {label}")
    return value


def _string(value: Any, label: str) -> None:
    if not isinstance(value, str):
        raise CorpusError(f"observation: invalid {label}")


def _boolean(value: Any, label: str) -> None:
    if not isinstance(value, bool):
        raise CorpusError(f"observation: invalid {label}")


def _artifacts(value: Any) -> None:
    if not isinstance(value, list):
        raise CorpusError("observation: rawArtifacts must be an array")
    for artifact in value:
        row = _exact_object(artifact, {"path", "sha256"}, "raw artifact")
        path, digest = row["path"], row["sha256"]
        if not isinstance(path, str) or not path or Path(path).is_absolute() or ".." in Path(path).parts or not isinstance(digest, str) or len(digest) != 64 or any(char not in "0123456789abcdef" for char in digest):
            raise CorpusError("observation: invalid raw artifact")


def _fact_value(fact: str, value: Any) -> None:
    if fact == "outcome":
        if value not in {"accepted", "rejected", "unknown"}: raise CorpusError("observation: invalid outcome fact")
    elif fact == "stage":
        row = _exact_object(value, {"stage", "reason"}, "stage fact"); _string(row["stage"], "stage")
        if row["reason"] is not None: _string(row["reason"], "stage reason")
    elif fact == "variables":
        _variables(value)
    elif fact == "source_closure":
        _closure(value)
    elif fact == "resolution":
        _resolution(value)
    elif fact == "levels":
        _levels(value)
    elif fact == "substitution":
        _substitutions(value)


def _variables(value: Any) -> None:
    if not isinstance(value, list): raise CorpusError("observation: variables must be an array")
    for row in value:
        item = _exact_object(row, {"name", "declaredIn", "declaredName"} | ({"importPath"} if isinstance(row, dict) and "importPath" in row else set()), "variable")
        for key in ("name", "declaredIn", "declaredName"): _string(item[key], key)
        if "importPath" in item and (not isinstance(item["importPath"], list) or not all(isinstance(part, str) for part in item["importPath"])): raise CorpusError("observation: invalid importPath")


def _closure(value: Any) -> None:
    if not isinstance(value, list): raise CorpusError("observation: source closure must be an array")
    for row in value:
        item = _exact_object(row, {"module", "path", "sha256"}, "source closure")
        _string(item["module"], "module"); _string(item["path"], "source path")
        digest = item["sha256"]
        if not isinstance(digest, str) or len(digest) != 64 or any(char not in "0123456789abcdef" for char in digest): raise CorpusError("observation: invalid source digest")


def _resolution(value: Any) -> None:
    root = _exact_object(value, {"dependencies", "operators"}, "resolution")
    if not isinstance(root["dependencies"], list) or not isinstance(root["operators"], list): raise CorpusError("observation: invalid resolution collections")
    for row in root["dependencies"]:
        item = _exact_object(row, {"owner", "dependency", "kind", "local"}, "dependency")
        for key in ("owner", "dependency", "kind"): _string(item[key], key)
        if item["kind"] not in {"extends", "namedInstance", "unnamedInstance"}: raise CorpusError("observation: invalid dependency kind")
        _boolean(item["local"], "dependency local")
    for row in root["operators"]:
        item = _exact_object(row, {"name", "declaredIn", "arity", "local"}, "operator")
        _string(item["name"], "operator name"); _string(item["declaredIn"], "operator declaredIn"); _boolean(item["local"], "operator local")
        if type(item["arity"]) is not int or item["arity"] < 0: raise CorpusError("observation: invalid operator arity")


def _levels(value: Any) -> None:
    if not isinstance(value, list): raise CorpusError("observation: levels must be an array")
    for row in value:
        item = _exact_object(row, {"name", "declaredIn", "level"}, "level")
        _string(item["name"], "level name"); _string(item["declaredIn"], "level declaredIn")
        if item["level"] not in {"constant", "state", "action", "temporal"}: raise CorpusError("observation: invalid operator level")


def _substitutions(value: Any) -> None:
    if not isinstance(value, list): raise CorpusError("observation: substitutions must be an array")
    for row in value:
        item = _exact_object(row, {"owner", "name", "module", "local", "line", "substitutions"}, "instance")
        for key in ("owner", "module"): _string(item[key], key)
        if item["name"] is not None: _string(item["name"], "instance name")
        _boolean(item["local"], "instance local")
        if type(item["line"]) is not int or item["line"] < 1 or not isinstance(item["substitutions"], list): raise CorpusError("observation: invalid instance")
        for substitution in item["substitutions"]:
            sub = _exact_object(substitution, {"formal", "actual", "implicit"}, "substitution")
            _string(sub["formal"], "substitution formal"); _boolean(sub["implicit"], "substitution implicit")
            actual = _exact_object(sub["actual"], {"kind", "value"}, "substitution actual")
            expected_type = {"name": str, "integer": int, "boolean": bool, "string": str}.get(actual["kind"])
            if expected_type is None or type(actual["value"]) is not expected_type or (actual["kind"] == "name" and not actual["value"]):
                raise CorpusError("observation: invalid substitution actual value")


def validate_registry(registry: Mapping[str, Any], fixtures: tuple[FixtureCapture, ...]) -> None:
    validate_contract("registry", registry)
    fixture_ids = {fixture.id for fixture in fixtures}
    for candidate in registry["candidates"]:
        if any(fixture_id not in fixture_ids for fixture_id in candidate["fixtureIds"]):
            raise CorpusError("registry: unknown fixture")
        if any(field not in FACT_IDS for field in candidate["fields"]):
            raise CorpusError("registry: unknown required fact")


def canonical_json(value: Mapping[str, Any]) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

code.tools/tla-differential/normalize.py:
"""Semantic projections shared by observations and comparisons.

Ordering is ignored only for set-like facts. Import routes are retained in raw
inspection evidence but are not treated as oracle-independent identity.
"""
from __future__ import annotations

import json


def ordered(values):
    return sorted(values, key=lambda value: json.dumps(value, sort_keys=True))


def supported(value):
    return {"capability": "supported", "value": value}


def mirrors_facts(document):
    inspection = document["inspection"]
    modules = document["modules"]
    local = {module["name"] for module in modules}
    operators = [op for op in inspection["operators"] if op["declaredIn"] in local]
    facts = {
        "source_closure": supported(ordered([
            {key: source[key] for key in ("module", "path", "sha256")}
            for source in inspection["sources"]])),
        "variables": supported([
            {key: variable[key] for key in ("name", "declaredIn", "declaredName", "importPath")}
            for variable in inspection["variables"]]),
        "resolution": supported({
            "dependencies": ordered([{key: edge[key] for key in ("owner", "dependency", "kind", "local")}
                                     for edge in inspection["dependencies"] if edge["resolution"] == "local"]),
            "operators": ordered([{key: op[key] for key in ("name", "declaredIn", "arity", "local")}
                                  for op in operators])}),
        "levels": supported(ordered([{key: op[key] for key in ("name", "declaredIn", "level")}
                                     for op in operators])),
    }
    instances = []
    complete = True
    by_module = {module["name"]: module for module in modules}
    for module in modules:
        for instance in module["instances"]:
            value = {key: instance[key] for key in ("owner", "name", "module", "local")}
            # Site line disambiguates multiple unnamed instances in one owner.
            value["line"] = instance["line"]
            substitutions = list(instance["substitutions"])
            child = by_module.get(instance["module"])
            if child is None:
                complete = False
            else:
                formals = [name for decl in child["declarations"]
                           if decl["kind"] in ("constant", "variable") for name in decl["names"]]
                explicit = {sub["formal"] for sub in substitutions}
                # A successful frontend has already admitted same-name implicit
                # substitution. This records that language rule, without parsing.
                substitutions += [{"formal": name, "actual": {"kind": "name", "value": name}, "implicit": True}
                                  for name in formals if name not in explicit]
            if any(sub["actual"] is None for sub in substitutions):
                complete = False
            value["substitutions"] = ordered(substitutions)
            instances.append(value)
    facts["substitution"] = supported(ordered(instances)) if complete else {"capability": "unqualified"}
    return facts

code.tools/tla-differential/process.py:
"""Bounded, hermetic subprocess execution for differential-tool adapters.

This module deliberately knows nothing about fixture capture or adapter output.
In particular, a non-zero exit is a completed execution: adapters decide whether
the tool's own result denotes language rejection.  Only a signal termination or
one of the enforced execution bounds changes the execution status here.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
import os
from pathlib import Path
import signal
import shutil
import subprocess
import threading
import time
from typing import Callable, Mapping, Sequence


DEFAULT_TIMEOUT_SECONDS = 60.0
DEFAULT_MAX_OUTPUT_BYTES = 8 * 1024 * 1024
DEFAULT_MAX_ARTIFACT_BYTES = 64 * 1024 * 1024


class ExecutionStatus(str, Enum):
    """Statuses used by the differential observation contract.

    ``INVALID_OUTPUT`` is intentionally not produced by this transport layer;
    adapters assign it after parsing a completed tool response.
    """

    COMPLETED = "completed"
    UNAVAILABLE = "unavailable"
    TIMEOUT = "timeout"
    CRASH = "crash"
    INVALID_OUTPUT = "invalid_output"
    RESOURCE_EXHAUSTED = "resource_exhausted"


@dataclass(frozen=True)
class ProcessLimits:
    """Execution ceilings.

    Artifact directories are sampled at the runner poll interval, so a writer
    can briefly overshoot ``max_artifact_bytes`` by up to one polling window.
    The oversized tree is discarded before this function returns.
    """

    timeout_seconds: float = DEFAULT_TIMEOUT_SECONDS
    max_stdout_bytes: int = DEFAULT_MAX_OUTPUT_BYTES
    max_stderr_bytes: int = DEFAULT_MAX_OUTPUT_BYTES
    max_artifact_bytes: int = DEFAULT_MAX_ARTIFACT_BYTES

    def __post_init__(self) -> None:
        if self.timeout_seconds <= 0:
            raise ValueError("timeout_seconds must be positive")
        for name in ("max_stdout_bytes", "max_stderr_bytes", "max_artifact_bytes"):
            if getattr(self, name) < 0:
                raise ValueError(f"{name} must not be negative")


@dataclass(frozen=True)
class ProcessRequest:
    """A direct executable invocation; shell syntax is not accepted."""

    argv: Sequence[str]
    cwd: Path
    environment: Mapping[str, str] = field(default_factory=dict)
    artifact_dir: Path | None = None

    def __post_init__(self) -> None:
        if not self.argv:
            raise ValueError("argv must contain an executable")
        if any(not isinstance(argument, str) or "\x00" in argument for argument in self.argv):
            raise ValueError("argv entries must be strings without NUL bytes")
        if not self.cwd.is_dir():
            raise ValueError(f"cwd is not a directory: {self.cwd}")
        if self.artifact_dir is not None:
            if not self.artifact_dir.is_dir() or self.artifact_dir.is_symlink():
                raise ValueError(f"artifact_dir must be a non-symlink directory: {self.artifact_dir}")
            cwd = self.cwd.resolve()
            artifact_dir = self.artifact_dir.resolve()
            if artifact_dir == cwd or cwd not in artifact_dir.parents:
                raise ValueError("artifact_dir must be strictly below cwd")
            if any(self.artifact_dir.iterdir()):
                raise ValueError("artifact_dir must be initially empty")
        for key, value in self.environment.items():
            if (
                not isinstance(key, str)
                or not isinstance(value, str)
                or not key
                or "=" in key
                or "\x00" in key
                or "\x00" in value
            ):
                raise ValueError("environment contains an invalid key or value")


@dataclass(frozen=True)
class ProcessResult:
    status: ExecutionStatus
    returncode: int | None
    stdout: bytes
    stderr: bytes
    elapsed_seconds: float
    artifact_bytes: int | None
    detail: str | None = None


def deterministic_environment(overrides: Mapping[str, str] = {}) -> dict[str, str]:
    """Return the complete environment inherited by a tool invocation.

    The caller must explicitly supply any tool-specific path such as a Java
    runtime or module search path.  This avoids accidental dependence on a
    developer's locale, home directory, or ambient TLA+/JVM configuration.
    """

    environment = {
        "LANG": "C",
        "LC_ALL": "C",
        "NO_COLOR": "1",
        "PATH": os.defpath,
        "PYTHONIOENCODING": "utf-8",
        "SOURCE_DATE_EPOCH": "0",
        "TERM": "dumb",
        "TZ": "UTC",
    }
    environment.update(overrides)
    return environment


def _directory_size(directory: Path) -> int:
    """Count regular artifact bytes without following links outside the bundle."""

    total = 0
    for path in directory.rglob("*"):
        try:
            if path.is_file() and not path.is_symlink():
                total += path.stat().st_size
        except FileNotFoundError:
            # A tool can remove a transient artifact while this monitor walks it.
            continue
    return total


def _discard_artifacts(directory: Path) -> None:
    """Remove an over-limit invocation tree before it can enter retained evidence."""

    shutil.rmtree(directory)
    directory.mkdir()


def _process_group_exists(process_group_id: int) -> bool:
    try:
        os.killpg(process_group_id, 0)
    except ProcessLookupError:
        return False
    return True


def _terminate_process_group(process: subprocess.Popen[bytes]) -> None:
    """End every POSIX group member, including children of an exited leader."""

    if os.name == "posix":
        process_group_id = process.pid
        try:
            os.killpg(process_group_id, signal.SIGTERM)
        except ProcessLookupError:
            return
        deadline = time.monotonic() + 0.2
        while time.monotonic() < deadline:
            if not _process_group_exists(process_group_id):
                return
            time.sleep(0.01)
        if _process_group_exists(process_group_id):
            try:
                os.killpg(process_group_id, signal.SIGKILL)
            except ProcessLookupError:
                pass
        return

    # Windows has no stdlib equivalent of POSIX killpg. CREATE_NEW_PROCESS_GROUP
    # lets Console tools receive CTRL_BREAK_EVENT; terminating the direct process
    # remains the portable fallback. CI support for recursive Windows cleanup must
    # be supplied by the runner's platform-specific containment layer.
    process.terminate()


def _stream_reader(
    stream: object,
    maximum: int,
    captured: bytearray,
    exceeded: threading.Event,
) -> None:
    # BufferedReader.read(n) may wait for n bytes, hiding a small flood until
    # process exit. read1 observes each currently available pipe chunk instead.
    read = getattr(stream, "read1", None)
    if read is None:
        read = getattr(stream, "read")
    while True:
        chunk = read(64 * 1024)
        if not chunk:
            return
        remaining = maximum - len(captured)
        if remaining > 0:
            captured.extend(chunk[:remaining])
        if len(chunk) > remaining:
            exceeded.set()


def run_process(
    request: ProcessRequest,
    limits: ProcessLimits = ProcessLimits(),
    *,
    popen_factory: Callable[..., subprocess.Popen[bytes]] = subprocess.Popen,
    monotonic: Callable[[], float] = time.monotonic,
    poll_interval_seconds: float = 0.02,
) -> ProcessResult:
    """Run one direct command with bounded streams, artifacts, and lifetime."""

    if poll_interval_seconds <= 0:
        raise ValueError("poll_interval_seconds must be positive")

    started = monotonic()
    try:
        process = popen_factory(
            list(request.argv),
            cwd=request.cwd,
            env=deterministic_environment(request.environment),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            shell=False,
            start_new_session=os.name == "posix",
            creationflags=(subprocess.CREATE_NEW_PROCESS_GROUP if os.name == "nt" else 0),
        )
    except OSError as error:
        return ProcessResult(
            ExecutionStatus.UNAVAILABLE, None, b"", b"", monotonic() - started, None, str(error)
        )

    assert process.stdout is not None
    assert process.stderr is not None
    stdout, stderr = bytearray(), bytearray()
    stdout_exceeded, stderr_exceeded = threading.Event(), threading.Event()
    readers = [
        threading.Thread(target=_stream_reader, args=(process.stdout, limits.max_stdout_bytes, stdout, stdout_exceeded)),
        threading.Thread(target=_stream_reader, args=(process.stderr, limits.max_stderr_bytes, stderr, stderr_exceeded)),
    ]
    for reader in readers:
        reader.start()

    status = ExecutionStatus.COMPLETED
    detail: str | None = None
    artifact_bytes: int | None = None
    try:
        while True:
            if process.poll() is not None:
                # The leader can exit while a background child still owns the
                # pipes and artifacts. Every invocation owns its whole group.
                process.wait()
                _terminate_process_group(process)
                break
            elapsed = monotonic() - started
            if elapsed >= limits.timeout_seconds:
                status, detail = ExecutionStatus.TIMEOUT, "process exceeded timeout"
            elif stdout_exceeded.is_set() or stderr_exceeded.is_set():
                status, detail = ExecutionStatus.RESOURCE_EXHAUSTED, "process exceeded output limit"
            elif request.artifact_dir is not None:
                artifact_bytes = _directory_size(request.artifact_dir)
                if artifact_bytes > limits.max_artifact_bytes:
                    status, detail = ExecutionStatus.RESOURCE_EXHAUSTED, "process exceeded artifact limit"
            if status is not ExecutionStatus.COMPLETED:
                _terminate_process_group(process)
                break
            time.sleep(poll_interval_seconds)

        try:
            returncode = process.wait(timeout=1)
        except subprocess.TimeoutExpired:
            _terminate_process_group(process)
            returncode = process.wait()
    except BaseException:
        # The subprocess has a separate session, so an interrupted Python
        # runner must explicitly end the complete tool group before propagating.
        _terminate_process_group(process)
        try:
            process.wait(timeout=1)
        except subprocess.TimeoutExpired:
            pass
        for reader in readers:
            reader.join()
        process.stdout.close()
        process.stderr.close()
        raise
    else:
        for reader in readers:
            reader.join()
        process.stdout.close()
        process.stderr.close()

    if status is ExecutionStatus.COMPLETED and (stdout_exceeded.is_set() or stderr_exceeded.is_set()):
        status, detail = ExecutionStatus.RESOURCE_EXHAUSTED, "process exceeded output limit"
    if request.artifact_dir is not None:
        artifact_bytes = _directory_size(request.artifact_dir)
        if artifact_bytes > limits.max_artifact_bytes:
            observed_bytes = artifact_bytes
            _discard_artifacts(request.artifact_dir)
            artifact_bytes = 0
            if status is ExecutionStatus.COMPLETED:
                status, detail = ExecutionStatus.RESOURCE_EXHAUSTED, "process exceeded artifact limit"
            detail = f"{detail}; discarded {observed_bytes} retained artifact bytes"
    if status is ExecutionStatus.COMPLETED and returncode < 0:
        status, detail = ExecutionStatus.CRASH, f"process terminated by signal {-returncode}"

    return ProcessResult(status, returncode, bytes(stdout), bytes(stderr), monotonic() - started, artifact_bytes, detail)

